window.HOEREN_TESTS[50] = {"id":"beim-augenarzt","name":"Beim Augenarzt","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Patienten: Die Augenarztpraxis Dr. Schwarz ist nächste Woche geschlossen. Notfälle bitte zur Klinik am Hauptbahnhof. Wir sagen Routinetermine nicht ab, und sie finden auch nicht normal statt. Wir verschieben sie und rufen alle Patienten persönlich an. Ab Montag in zwei Wochen sind wir wieder da. Vielen Dank für Ihr Verständnis!","gender":"f","q":"Was passiert mit Routineterminen?","opts":["Sie werden abgesagt.","Sie werden verschoben.","Sie finden normal statt."],"correct":1},{"transcript":"Hallo Lisa, hier ist Anna. Ich brauche eine neue Brille, meine alte ist letzte Woche kaputt gegangen. Im Optiker-Geschäft bei mir kosten Brillen 200 Euro, online sind sie billig, aber ich will das nicht. Bei meinem Augenarzt nur 150 Euro, inklusive Untersuchung. Ich kaufe die Brille lieber beim Augenarzt. Was meinst du? Ruf zurück.","gender":"f","q":"Wo kauft Anna die Brille?","opts":["Im Optiker-Geschäft.","Online.","Beim Augenarzt."],"correct":2},{"transcript":"Achtung Patienten: Wir haben jetzt neue Kontakt-Linsen im Angebot. Monats-Linsen kosten 30 Euro pro Box, Tages-Linsen 50 Euro. Auch Bio-Linsen für sensible Augen, 80 Euro, aber sehr angenehm. Beratung gerne bei uns. Ein Termin ist nötig, bitte vorher anrufen oder online buchen. Wir helfen Ihnen gern bei der Auswahl!","gender":"m","q":"Was kosten Monats-Linsen?","opts":["30 Euro.","50 Euro.","80 Euro."],"correct":0},{"transcript":"Hi Markus, hier ist Tom. Also, mein Sohn sieht schlecht in der Schule, er sitzt vorne und kann die Tafel kaum lesen. Ich selbst gehe nicht zum Augenarzt, und meine Mutter auch nicht als Patientin. Morgen hat mein Sohn den Termin, vielleicht braucht er eine Brille, mit 8 Jahren schon. Mama kommt nur mit, weil sie Kinder gut kennt.","gender":"m","q":"Wer geht zum Augenarzt?","opts":["Toms Sohn.","Tom.","Toms Mutter."],"correct":0},{"transcript":"Liebe Eltern: Die Schule bietet eine kostenlose Augen-Untersuchung für alle Erstklässler. Termine am Mittwoch und Freitag in der Aula. Bitte den Erlaubnis-Zettel unterschreiben. Schüler ohne Brille sollen kommen. Wer schon eine Brille hat, muss nicht kommen. Niemand mit Brille braucht den Test. Bei Problemen wenden Sie sich an die Schule.","gender":"f","q":"Wer muss nicht kommen?","opts":["Schüler ohne Brille.","Niemand.","Schüler mit Brille."],"correct":2}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer trägt was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Der Augenarzt hat heute Nachmittag noch einen Termin frei."},{"speaker":"Lisa","gender":"f","text":"Schön, dass du anrufst. Ich sehe abends auf der Straße fast nichts."},{"speaker":"Lukas","gender":"m","text":"Ich nehme eine normale Brille. Beim Autofahren bleibt die Straße sonst unscharf."},{"speaker":"Lisa","gender":"f","text":"Die passt gut zu dir. Ich möchte Kontaktlinsen für jeden Tag. Die sind leicht im Alltag."},{"speaker":"Lukas","gender":"m","text":"Braucht jemand eine Sportbrille fürs Training?"},{"speaker":"Lisa","gender":"f","text":"Nein. Eine Sportbrille nimmt niemand von uns."},{"speaker":"Lukas","gender":"m","text":"Tom liest abends lange auf dem Sofa."},{"speaker":"Lisa","gender":"f","text":"Tom braucht nur eine Lesebrille. Für Bücher reicht ihm das völlig."},{"speaker":"Lukas","gender":"m","text":"Sara fährt im Sommer oft ans Meer und die Sonne blendet sie stark."},{"speaker":"Lisa","gender":"f","text":"Dann nimmt Sara eine Sonnenbrille mit Sehstärke. Die sitzt fest auf der Nase."},{"speaker":"Lukas","gender":"m","text":"Nimmt jemand die Computer-Brille für lange Tage am Bildschirm?"},{"speaker":"Lisa","gender":"f","text":"Nein. Wir kaufen keine Computer-Brille."},{"speaker":"Lukas","gender":"m","text":"Tim hat die Gläser satt und will im Herbst endlich scharf sehen."},{"speaker":"Lisa","gender":"f","text":"Tim plant eine Augen-Operation mit Laser. Danach sieht er wieder klar."},{"speaker":"Lukas","gender":"m","text":"Dann treffen wir uns um drei in der Praxis."},{"speaker":"Lisa","gender":"f","text":"Bis nachher. Ich komme pünktlich mit der Karte."}],"options":[{"letter":"a","text":"Keine Sehhilfe"},{"letter":"b","text":"Sportbrille"},{"letter":"c","text":"Lesebrille"},{"letter":"d","text":"Bifokal-Brille"},{"letter":"e","text":"Normale Brille"},{"letter":"f","text":"Computer-Brille"},{"letter":"g","text":"Kontaktlinsen"},{"letter":"h","text":"Augen-Operation"},{"letter":"i","text":"Sonnenbrille mit Sehstärke"}],"items":[{"person":"Lukas","correct":"e"},{"person":"Lisa","correct":"g"},{"person":"Tom","correct":"c"},{"person":"Sara","correct":"i"},{"person":"Tim","correct":"h"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Patientin","gender":"f","text":"Guten Tag Doktor, ich sehe schlecht in der Ferne, zum Beispiel beim Autofahren."},{"speaker":"Arzt","gender":"m","text":"Lassen Sie mich messen. Setzen Sie sich bitte dort hin, das dauert nur ein paar Minuten."},{"speaker":"Patientin","gender":"f","text":"Brauche ich eine Brille, oder gehen auch Kontaktlinsen? Oder gar nichts?"},{"speaker":"Arzt","gender":"m","text":"Sie brauchen etwas, nichts tun ist keine gute Idee. Minus 1,5 Dioptrien, Brille oder Kontaktlinsen."},{"speaker":"Patientin","gender":"f","text":"Dann nehme ich eine Brille. Linsen mag ich nicht, das ist mir unangenehm auf dem Auge."}],"q":"Was wählt sie?","opts":["Brille.","Kontaktlinsen.","Nichts."],"correct":0},{"lines":[{"speaker":"Kunde","gender":"m","text":"Diese Brille gefällt mir sehr, die schwarze dort im Fenster. Was kostet sie mit Gläsern?"},{"speaker":"Optikerin","gender":"f","text":"Die kostet 350 Euro mit Gläsern. Es gibt auch ein ähnliches Modell für 220 Euro."},{"speaker":"Kunde","gender":"m","text":"350 Euro ist ein bisschen viel. Gibt es die Form günstiger, oder soll ich keine nehmen?"},{"speaker":"Optikerin","gender":"f","text":"Diese da, gleiche Form, 220 Euro. Keine Brille ist keine Lösung, Sie brauchen eine."},{"speaker":"Kunde","gender":"m","text":"Gut, die für 220 Euro nehme ich. Die für 350 ist mir zu teuer. Danke!"}],"q":"Welche Brille kauft er?","opts":["220 Euro Brille.","350 Euro Brille.","Keine."],"correct":0},{"lines":[{"speaker":"Mutter","gender":"f","text":"Klein-Tim braucht eine Brille, der Arzt hat das heute gesagt. Ich bin ganz überrascht."},{"speaker":"Vater","gender":"m","text":"So jung? Brauchst du eine neue, oder ich? Ich sehe doch noch gut."},{"speaker":"Mutter","gender":"f","text":"Ich habe schon eine Brille, du brauchst keine. Aber Tim ist mit 6 schon kurzsichtig wie ich."},{"speaker":"Vater","gender":"m","text":"Gibt es bunte Kinder-Brillen? Blau oder rot, dann wählt er selbst."},{"speaker":"Mutter","gender":"f","text":"Ja, er wählt selbst. Wichtig ist nur, dass Klein-Tim die Brille bekommt."}],"q":"Wer braucht eine Brille?","opts":["Mutter.","Klein-Tim.","Vater."],"correct":1},{"lines":[{"speaker":"Frau","gender":"f","text":"Guten Tag, wann ist meine neue Brille fertig? Ich brauche sie für die Arbeit."},{"speaker":"Optiker","gender":"m","text":"Normal in einer Woche. Express geht in 3 Tagen, aber mit 50 Euro Aufschlag. Zwei Wochen nur bei Spezial-Gläsern."},{"speaker":"Frau","gender":"f","text":"Eine Woche ist lang, zwei Wochen geht gar nicht. Geht Express in 3 Tagen?"},{"speaker":"Optiker","gender":"m","text":"Ja, Express in 3 Tagen. Dann zahlen Sie 50 Euro mehr, ist das okay?"},{"speaker":"Frau","gender":"f","text":"Okay, dann Express, 3 Tage. Ich hole die Brille am Donnerstag ab. Danke!"}],"q":"Wann ist die Brille fertig?","opts":["Zwei Wochen.","Eine Woche.","3 Tage."],"correct":2},{"lines":[{"speaker":"Junge","gender":"m","text":"Mama, meine normale Brille ist kaputt. Die liegt in zwei Teilen auf dem Boden."},{"speaker":"Mutter","gender":"f","text":"Schon wieder? Was ist passiert, hast du Linsen verloren oder nur die Brille?"},{"speaker":"Junge","gender":"m","text":"Beim Fußball, jemand hat mich angestoßen. Linsen will ich nicht, die mag ich nicht."},{"speaker":"Mutter","gender":"f","text":"Beim Sport keine neue normale Brille. Wir holen dir eine Sportbrille, die hält besser."},{"speaker":"Junge","gender":"m","text":"Okay, eine Sportbrille. Die normale lasse ich nur für die Schule, ja?"}],"q":"Was bekommt der Junge?","opts":["Neue normale Brille.","Sportbrille.","Linsen."],"correct":1}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Doktor Stein, einer Augenärztin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Doktor Stein, Sie arbeiten als Augenärztin seit 20 Jahren. Was sind heute die häufigsten Probleme?"},{"speaker":"Stein","gender":"f","text":"Kurzsichtigkeit, vor allem bei Kindern und jungen Leuten. Vor 20 Jahren waren etwa 30 Prozent kurzsichtig, heute über 50 Prozent. Bildschirme sind schuld — Handy, Tablet, Computer den ganzen Tag."},{"speaker":"Reporter","gender":"m","text":"Was raten Sie Eltern?"},{"speaker":"Stein","gender":"f","text":"Kinder weniger vor Bildschirm — höchstens zwei Stunden täglich. Viel draußen spielen, weil Tageslicht schützt die Augen. Wenn schon Bildschirm, alle 20 Minuten kurze Pause, in die Ferne schauen. Hilft."},{"speaker":"Reporter","gender":"m","text":"Wie ist es mit älteren Patienten?"},{"speaker":"Stein","gender":"f","text":"Ab 40 wird fast jeder weitsichtig — Lesebrille nötig. Auch grauer Star kommt mit Alter. Operation hilft sehr gut — heute Routine, schnell und sicher. Viele freuen sich danach über besseres Sehen."},{"speaker":"Reporter","gender":"m","text":"Was ist mit Lasik-Operationen?"},{"speaker":"Stein","gender":"f","text":"Sehr beliebt heute. Aber nicht für jeden — Augen müssen stabil sein, dünne Hornhaut ist Problem. Kosten 2000 bis 3000 Euro pro Auge. Krankenkasse zahlt nicht, ist Privatsache. Wir machen das nicht in unserer Praxis."},{"speaker":"Reporter","gender":"m","text":"Was ist Ihr Rat allgemein?"},{"speaker":"Stein","gender":"f","text":"Regelmäßige Kontrollen — alle zwei Jahre mindestens. Augen schonen — Sonnenbrille bei Sonne, Schutzbrille beim Sport. Gesunde Ernährung — viele Karotten und grünes Gemüse — hilft den Augen wirklich."}],"items":[{"q":"Kurzsichtigkeit ist heute häufiger als vor 20 Jahren.","correct":"ja"},{"q":"Sie rät Eltern, Kinder mehr draußen spielen zu lassen.","correct":"ja"},{"q":"Frau Doktor Stein macht selbst Lasik-Operationen.","correct":"nein"},{"q":"Krankenkassen zahlen für Lasik-Operationen.","correct":"nein"},{"q":"Karotten helfen den Augen wirklich.","correct":"ja"}]}]};
